{"command":"cat <<'EOF' > executable.py
#!/usr/bin/env python3
import sys, os, re, threading
from concurrent.futures import ThreadPoolExecutor

RED, GREEN, MAGENTA, CYAN, RESET = '\033[1;31m', '\033[0;32m', '\033[0;35m', '\033[0;36m', '\033[0m'
prompt_lock = threading.Lock()
replace_all = False
quit_program = False

def print_help():
    print("""ambr 0.6.0

USAGE:
    executable [FLAGS] [OPTIONS] <KEYWORD> <REPLACEMENT> [PATHS]...

FLAGS:
        --key-from-file        Use file contents of KEYWORD as keyword for search
        --rep-from-file        Use file contents of REPLACEMENT as keyword for replacement
        --verbose              Verbose message
    -r, --regex                Enable regular expression search
        --column               Enable column output
        --row                  Enable row output
        --binary               Enable binary file search
        --statistics           Enable statistics output
        --skipped              Enable skipped file output
        --preserve-time        Enable timestamp preserve
        --no-interactive       Disable interactive replace
        --no-recursive         Disable recursive directory search
        --no-symlink           Disable symbolic link follow
        --no-color             Disable colored output
        --no-file              Disable filename output
        --no-skip-vcs          Disable vcs directory ( .hg/.git/.svn ) skip
        --no-skip-gitignore    Disable .gitignore skip
        --no-fixed-order       Disable output order guarantee
        --no-parent-ignore     Disable .*ignore file search at parent directories
        --tbm                  [Experimental] Enable TBM matcher
        --sse                  [Experimental] Enable SSE 4.2
    -h, --help                 Prints help information
    -V, --version              Prints version information

OPTIONS:
        --max-threads <NUM>          Number of max threads [default: 20]
        --size-per-thread <BYTES>    File size per one thread [default: 1048576]
        --bin-check-bytes <BYTES>    Read size for checking binary [default: 256]
        --mmap-bytes <BYTES>         [Experimental] Minimum size for using mmap [default: 1048576]

ARGS:
    <KEYWORD>        Keyword for search
    <REPLACEMENT>    Keyword for replace
    <PATHS>...       Search paths""")

def is_binary(path, bin_check_bytes):
    try:
        with open(path, 'rb') as f:
            return b'\x00' in f.read(bin_check_bytes)
    except: return True

def transform_regex(regex):
    return re.sub(r'\(\?<([a-zA-Z_][a-zA-Z0-9_]*)>', r'(?P<\1>', regex)

def transform_replacement(rep):
    res, i = "", 0
    while i < len(rep):
        if rep[i] == '$':
            if i + 1 < len(rep):
                if rep[i+1] == '{':
                    end = rep.find('}', i + 2)
                    if end != -1:
                        res += "\\g<" + rep[i+2:end] + ">"; i = end + 1; continue
                elif rep[i+1].isdigit():
                    j = i + 1
                    while j < len(rep) and rep[j].isdigit(): j += 1
                    res += "\\g<" + rep[i+1:j] + ">"; i = j; continue
                elif rep[i+1].isalpha() or rep[i+1] == '_':
                    j = i + 1
                    while j < len(rep) and (rep[j].isalnum() or rep[j] == '_'): j += 1
                    res += "\\g<" + rep[i+1:j] + ">"; i = j; continue
        res += rep[i]; i += 1
    return res

def process_file(path, keyword, replacement, flags, options):
    global replace_all, quit_program
    if quit_program or (not flags['binary'] and is_binary(path, options['bin_check_bytes'])): return
    try:
        with open(path, 'r', errors='ignore') as f: content = f.read()
    except: return
    if flags['regex']:
        try:
            p_keyword, p_replacement = transform_regex(keyword), transform_replacement(replacement)
            matches = list(re.finditer(p_keyword, content))
        except: return
    else:
        matches, start = [], 0
        while True:
            idx = content.find(keyword, start)
            if idx == -1: break
            matches.append((idx, idx + len(keyword))); start = idx + len(keyword)
    if not matches: return
    new_content, last_idx, modified = "", 0, False
    for m in matches:
        if quit_program: break
        if flags['regex']:
            start, end = m.span(); matched_text = m.group(0)
            try: this_replacement = m.expand(p_replacement)
            except: this_replacement = replacement
        else: start, end = m; matched_text, this_replacement = keyword, replacement
        if flags['no_interactive'] or replace_all: do_replace = True
        else:
            with prompt_lock:
                if replace_all: do_replace = True
                elif quit_program: do_replace = False
                else:
                    line_start = content.rfind('\n', 0, start) + 1
                    line_end = content.find('\n', end)
                    if line_end == -1: line_end = len(content)
                    line_content = content[line_start:line_end]
                    line_num, col_num = content.count('\n', 0, start) + 1, start - line_start + 1
                    if not flags['no_file']: print(f"{MAGENTA}{path}{RESET}")
                    prefix = f"{GREEN}{line_num}{RESET}:"
                    if flags['column']: prefix += f"{CYAN}{col_num}{RESET}:"
                    print(f"{prefix}{line_content[:start-line_start]}{RED}{matched_text}{RESET}{line_content[end-line_start:]}")
                    while True:
                        print("Replace keyword? ( Yes[y], No[n], All[a], Quit[q] ): ", end='', flush=True)
                        ans = sys.stdin.readline().strip().lower()
                        if ans in ['y', 'yes']: do_replace = True; break
                        elif ans in ['n', 'no']: do_replace = False; break
                        elif ans in ['a', 'all']: replace_all = True; do_replace = True; break
                        elif ans in ['q', 'quit']: quit_program = True; do_replace = False; break
        if do_replace: new_content += content[last_idx:start] + this_replacement; last_idx, modified = end, True
        else: new_content += content[last_idx:end]; last_idx = end
    new_content += content[last_idx:]
    if modified:
        if flags['preserve_time']: st = os.stat(path); atime, mtime = st.st_atime, st.st_mtime
        with open(path, 'w') as f: f.write(new_content)
        if flags['preserve_time']: os.utime(path, (atime, mtime))

def main():
    if "--help" in sys.argv or "-h" in sys.argv: print_help(); return
    if "--version" in sys.argv or "-V" in sys.argv: print("ambr 0.6.0"); return
    flags = {f: False for f in ['regex', 'column', 'row', 'binary', 'statistics', 'skipped', 'preserve_time', 'no_interactive', 'no_recursive', 'no_symlink', 'no_color', 'no_file', 'no_skip_vcs', 'no_skip_gitignore', 'no_fixed_order', 'no_parent_ignore', 'tbm', 'sse', 'key_from_file', 'rep_from_file', 'verbose']}
    options = {o: d for o, d in [('max_threads', 20), ('size_per_thread', 1048576), ('bin_check_bytes', 256), ('mmap_bytes', 1048576)]}
    pos_args, i = [], 1
    while i < len(sys.argv):
        arg = sys.argv[i]
        if arg.startswith('--'):
            name = arg[2:].replace('-', '_')
            if name in flags: flags[name] = True
            elif name in options:
                if i+1 < len(sys.argv): options[name] = int(sys.argv[i+1]); i += 1
                else: print(f"error: The argument '{arg}' requires a value but none was supplied"); sys.exit(1)
            else: print(f"error: Found argument '{arg}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    executable [FLAGS] [OPTIONS] <KEYWORD> <REPLACEMENT> [PATHS]...\n\nFor more information try --help"); sys.exit(1)
        elif arg.startswith('-') and len(arg) > 1:
            for char in arg[1:]:
                if char == 'r': flags['regex'] = True
                elif char == 'h': print_help(); return
                elif char == 'V': print("ambr 0.6.0"); return
                else: print(f"error: Found argument '-{char}' which wasn't expected\n\nUSAGE:\n    executable [FLAGS] [OPTIONS] <KEYWORD> <REPLACEMENT> [PATHS]...\n\nFor more information try --help"); sys.exit(1)
        else: pos_args.append(arg)
        i += 1
    if len(pos_args) < 1: print(f"error: The following required arguments were not provided:\n    <KEYWORD>\n    <REPLACEMENT>\n\nUSAGE:\n    executable <KEYWORD> <REPLACEMENT> --bin-check-bytes <BYTES> --max-threads <NUM> --mmap-bytes <BYTES> --size-per-thread <BYTES>\n\nFor more information try --help"); sys.exit(1)
    if len(pos_args) < 2: print(f"error: The following required arguments were not provided:\n    <REPLACEMENT>\n\nUSAGE:\n    executable <KEYWORD> <REPLACEMENT> --bin-check-bytes <BYTES> --max-threads <NUM> --mmap-bytes <BYTES> --size-per-thread <BYTES>\n\nFor more information try --help"); sys.exit(1)
    keyword, replacement = pos_args[0], pos_args[1]
    paths = pos_args[2:] if len(pos_args) > 2 else ['.']
    if flags['key_from_file']:
        with open(keyword, 'r') as f: keyword = f.read()
    if flags['rep_from_file']:
        with open(replacement, 'r') as f: replacement = f.read()
    file_list = []
    for p in paths:
        if os.path.isfile(p): file_list.append(p)
        elif os.path.isdir(p):
            for root, dirs, files in os.walk(p, followlinks=not flags['no_symlink']):
                if not flags['no_skip_vcs']: dirs[:] = [d for d in dirs if d not in ['.git', '.hg', '.svn', '.bzr']]
                if flags['no_recursive']: dirs[:] = []
                for f in files: file_list.append(os.path.join(root, f))
    with ThreadPoolExecutor(max_workers=options['max_threads']) as executor:
        for f in sorted(file_list): executor.submit(process_file, f, keyword, replacement, flags, options)

if __name__ == "__main__": main()
